# -*- coding: utf-8 -*-

cases = [
    {"id":"case-yitang-pet-fostering-user-research","title":"案例：宠物寄养——观察现有替代方案","group":"A","insight":"理解用户的最佳方式不是问“你会用我的产品吗”，而是观察“你现在怎么解决这个问题”——行为比语言更诚实。","failure":"跳过替代方案观察直接做产品。","frameworks":"tool-yitang-user-interview-5steps","surprise":"不急着做产品，先看用户在没有你产品时的真实替代方案。"},
    {"id":"case-yitang-doorstep-nail-service-context","title":"案例：上门美甲——在用户真实场景中访谈","group":"A","insight":"“魔鬼在现场”：在真实场景中观察+访谈的信息密度，远高于会议室访谈。","failure":"在会议室/微信里做脱离场景的访谈。","frameworks":"tool-yitang-user-interview-5steps、dk-yitang-research-scale-vs-depth","surprise":"同一用户在不同场景下说出的需求可能完全相反。"},
    {"id":"case-yitang-doorstep-pet-feeding-trust","title":"案例：上门宠物喂养——用调研解决信任障碍","group":"A","insight":"信任问题的解法往往不在本品类，而在相邻品类（家政/维修/月嫂）的最佳实践里。","failure":"把需求验证和信任验证混为一谈。","frameworks":"tool-yitang-user-interview-5steps","surprise":"用户不是不需要服务，而是不知道怎么让一个陌生人进自己家。"},
    {"id":"case-yitang-homestay-reception-design","title":"案例：民宿接待方案——用调研优化服务体验设计","group":"A","insight":"服务设计的调研重点是“看别人怎么做”+“听用户怎么骂”，二者相加才是改进清单。","failure":"拍脑袋写 SOP。","frameworks":"tool-yitang-user-interview-5steps","surprise":"竞对的 SOP 和用户的差评同样重要。"},
    {"id":"case-yitang-voice-robot-companion-design","title":"案例：陪伴式语音机器人——声音设计如何调研","group":"A","insight":"在新品类创新前，先调研旧品类（Siri/小爱/导航）的声音规律，人对声音的偏好有稳定模式。","failure":"先做一版再测试，无参照地“创新”。","frameworks":"tool-yitang-user-interview-5steps","surprise":"语音产品虽新，但声音偏好规律不必重新发明。"},
    {"id":"case-yitang-ski-project-user-as-expert","title":"案例：滑雪项目——把用户当专家访谈","group":"A","insight":"重度用户就是行业专家，他们对需求和替代方案的认知往往超过分析师。","failure":"只访谈行业分析师或普通用户，忽视重度用户。","frameworks":"framework-yitang-expert-interview-10steps、tool-yitang-user-interview-5steps","surprise":"用户调研和专家访谈的边界在深度用户身上是模糊的。"},
    {"id":"case-yitang-jtbd-story-formula","title":"案例：JTBD故事公式——从用户故事中提取需求","group":"A","insight":"JTBD 故事公式强制用户回溯真实行为路径，一个完整故事抵得上 100 份问卷。","failure":"直接问“你有什么需求”或只问观念。","frameworks":"tool-yitang-user-interview-5steps、yt-research-user-jtbd","surprise":"最有价值的信息是“我试过什么但不行”。"},
    {"id":"case-yitang-consumer-offline-channel-decision","title":"案例：消费品线下渠道决策——先访谈再算账","group":"A","insight":"渠道决策不能只靠行业报告，必须先访谈一线从业者拿真实数据，再用单元模型计算。","failure":"只看报告增长率，忽视进场费、账期、退货率。","frameworks":"tool-yitang-user-interview-5steps、tool-yitang-consumer-goods-research","surprise":"报告写增长率 15%，经销商说进场费半年涨了 30%。"},
    {"id":"case-yitang-mvp-reward-interview-waste","title":"案例：MVP阶段花钱做用户访谈的浪费","group":"A","insight":"用户访谈质量不取决于花了多少钱或样本量，而取决于是否访谈了对的人。","failure":"MVP 阶段未做用户画像就花钱做正式访谈/焦点小组。","frameworks":"framework-yitang-expert-interview-10steps、concept-ceo-must-do-user-research","surprise":"花大钱可能买到错误人群的错误反馈。"},
    {"id":"case-yitang-competitor-pricing-intelligence","title":"案例：假装订货套取竞品真实价格","group":"B","insight":"供应链端是商业情报的“软肋”——竞品可以对对手保密，却很难对“潜在客户”保密。","failure":"拿官网标价当真实价格。","frameworks":"tool-yitang-reverse-data-analysis、tool-yitang-social-engineering-research","surprise":"假装采购方不仅不会被防，还会拿到真实报价、折扣结构和账期。"},
    {"id":"case-yitang-mahjong-machine-fake-order","title":"案例：假装订货套取麻将机竞品数据","group":"B","insight":"“假装上下游角色”是获取竞品数据最高效的社会工程手段——你不是刺探者，而是“潜在大客户”。","failure":"直接询问竞品价格/出货量。","frameworks":"tool-yitang-reverse-data-analysis、tool-yitang-social-engineering-research","surprise":"对方会主动展示最好的一面，把真实批发价和折扣结构交给你。"},
    {"id":"case-yitang-supplier-security-guard","title":"案例：通过保安打听到工厂收购价","group":"B","insight":"供应链上任何“知道内情且愿意说”的人都可能掌握核心信息，不一定是高管。","failure":"只找工人/管理层，忽视长期在场的外围角色。","frameworks":"tool-yitang-supply-chain-research、tool-yitang-field-research","surprise":"24 小时在场的保安竟是股东亲戚，知道老板真实心理价位。"},
    {"id":"case-yitang-hardware-factory-photo","title":"案例：从朋友圈照片找到代工厂","group":"B","insight":"朋友圈照片的微小细节（工厂铭牌）可成为破解供应链的关键线索。","failure":"被拒绝两次后就放弃。","frameworks":"tool-yitang-supply-chain-research、dk-yitang-digging-belief","surprise":"花 3 小时放大照片角落，省下几十万开模费。"},
    {"id":"case-zhanglei-furniture-overseas-market-selection","title":"案例：张磊——洗衣液蹲超市+假扮促销员","group":"B","insight":"最原始的方法（蹲超市+假扮促销员）往往比报告更接近真实购买行为。","failure":"依赖问卷或二手报告判断新品类需求。","frameworks":"tool-yitang-field-research、tool-yitang-social-engineering-research","surprise":"蹲在货架前看 2 小时，比看 20 份消费者报告更接近真相。"},
    {"id":"case-zhanglan-amusement-park-undercover","title":"案例：张兰假扮游乐园店长卧底15天","group":"B","insight":"穿上工服、真正融入现场运营足够长时间，能拿到最不可篡改的一手信息。","failure":"“参观式调研”或短期观察。","frameworks":"tool-yitang-social-engineering-research、tool-yitang-field-research","surprise":"不需要高端方法，当 15 天服务员即可。"},
    {"id":"case-zhanglei-nursing-home-family","title":"案例：假扮孙子调研养老院真实状况","group":"C","insight":"线上潜入家属群+线下假扮家属的双重渗透，可互为交叉验证。","failure":"只看养老院宣传册/表面服务。","frameworks":"tool-yitang-social-engineering-research、tool-yitang-field-research","surprise":"在食堂吃饭、和其他家属聊天，能拿到宣传册永远不会写的内容。"},
    {"id":"case-yitang-elderly-home-roleplay","title":"案例：假扮家属潜入养老院微信群","group":"C","insight":"最关键的信息往往在“外部不可见但信息密集”的场景里（家属微信群），需要合法融入。","failure":"只看公开渠道和财务报表。","frameworks":"tool-yitang-social-engineering-research、tool-yitang-field-research","surprise":"假扮家属进群能拿到早期入住率爬坡曲线和真实满意度。"},
    {"id":"case-yitang-fake-interview-intelligence","title":"案例：假扮面试发现行业红利退潮","group":"C","insight":"用“面试者”身份渗透到多家公司内部，可发现活下来的玩家不愿说的系统性衰退。","failure":"只调研品牌方、头部公司、赚钱的同行。","frameworks":"tool-yitang-job-intelligence-research、tool-yitang-social-engineering-research","surprise":"面试一圈后发现红利期退潮，避免了大笔投资损失。"},
    {"id":"case-liutao-douyin-team-leader-9m","title":"案例：刘涛——从信息碎片拼出抖音团长赛道真相","group":"C","insight":"同一问题用多个身份（加盟商/亏钱同行/面试者/客户）从不同角度交叉验证，才能拼出完整图景。","failure":"相信单一来源或官方数据。","frameworks":"framework-yitang-high-level-execution、dk-yitang-digging-belief、tool-yitang-job-intelligence-research","surprise":"翻评论区、照片、朋友圈比高端工具更有效。"},
    {"id":"case-zhanglei-twist-egg-machine-yogurt-nursing","title":"案例：张磊——扭蛋机+酸奶+养老院，调研先行的连续创业","group":"C","insight":"连续创业成功的关键不是经验，而是每次进入新品类都用调研把认知空白填上。","failure":"凭过去经验跳过新领域调研。","frameworks":"framework-yitang-high-level-execution","surprise":"有经验的人反而更依赖调研，而不是跳过调研。"},
    {"id":"case-yitang-luckin-field-research","title":"案例：瑞幸做空——实地调研的教科书","group":"D","insight":"实地调研不需要“聪明”，需要“狠”——愿意投入足够的时间和人力。","failure":"想靠小聪明或小样本走捷径。","frameworks":"tool-yitang-field-research、framework-yitang-high-level-execution","surprise":"92 个全职+1400 多名兼职，收集 25000 多张小票，从财报中找出欺诈。"},
    {"id":"case-yitang-travel-receipt-analysis","title":"案例：旅行公司收据分析——从单据反推真实数据","group":"D","insight":"订单号、收据、小票等不起眼的数字是不可篡改的交易记录，可反推真实经营数据。","failure":"依赖财报/宣传数据。","frameworks":"tool-yitang-reverse-data-analysis、tool-yitang-field-research","surprise":"自增订单号可推算总订单量，小票拼起来比财报更真实。"},
    {"id":"case-doris-crossborder-ecommerce-opportunity","title":"案例：跨境电商机会识别——从报告到行动","group":"E","insight":"跨境电商是数据最丰富的行业之一，问题不是数据不够，而是不知道去哪找、怎么用。","failure":"品类/市场多而无目标地乱搜。","frameworks":"framework-doris-industry-report-4step","surprise":"海关有每一单的进出口数据。"},
    {"id":"case-doris-outbound-travel-community","title":"案例：出境游产业链拆解","group":"E","insight":"一份好行业报告里的产业链图，价值可能超过报告其他部分的总和。","failure":"通读报告不抓重点。","frameworks":"framework-doris-industry-report-4step","surprise":"一页图直接回答“谁赚什么钱”。"},
    {"id":"case-doris-catering-chain-benchmark","title":"案例：餐饮连锁对标调研","group":"E","insight":"餐饮连锁上市公司招股书把单店模型、翻台率、扩张节奏写得清清楚楚，可直接当 benchmark。","failure":"自己重新做实验。","frameworks":"framework-doris-industry-report-4step、tool-yitang-financial-report-intelligence","surprise":"别人的验证数据免费可得。"},
    {"id":"case-doris-grab-industry-cognition","title":"案例：Doris 7天从零建立行业认知","group":"E","insight":"不需要先成为专家才能判断——用 5 个关键信息点 7 天内达到能和专家平等对话的水平。","failure":"试图慢慢积累行业知识再下结论。","frameworks":"framework-doris-industry-report-4step、tool-doris-industry-report-search-tips","surprise":"28 页产业综述来自有限的初始关键词扩展。"},
    {"id":"case-doris-beauty-ecommerce-channel","title":"案例：美妆行业渠道效率发现","group":"E","insight":"行业报告里有现成的渠道效率数据，咨询公司×平台联合报告通常是高质量来源。","failure":"凭感觉选渠道。","frameworks":"framework-doris-industry-report-4step、tool-doris-industry-report-search-tips","surprise":"抖音/小红书转化效果来自贝恩×阿里妈妈联合报告。"},
    {"id":"case-doris-2014-music-streaming-prediction","title":"案例：2014年预判音乐流媒体趋势","group":"E","insight":"权威行业报告+正确解读框架可支撑融资级商业判断，关键是读出“稳态 B”。","failure":"只看报告本身，不读出不可逆趋势。","frameworks":"framework-doris-industry-report-4step","surprise":"IFPI 报告提前多年预判流媒体成为主流。"},
    {"id":"case-popmart-prospectus-pricing","title":"案例：泡泡玛特招股书——IP产品毛利率60-70%","group":"E","insight":"公开招股书是免费的 benchmark 报告，可判断自身定价/毛利是否合理。","failure":"花钱找咨询公司做基础定价基准。","frameworks":"tool-yitang-financial-report-intelligence、tool-yitang-ipo-annual-report-cheat-sheet","surprise":"招股书里的毛利率可直接当定价基准。"},
    {"id":"case-neworiental-prospectus-marketing","title":"案例：新东方招股书——营销渠道全览","group":"E","insight":"行业龙头的招股书等于已被大规模执行验证过的获客方法论。","failure":"自己从零摸索获客渠道。","frameworks":"tool-yitang-financial-report-intelligence","surprise":"公开文件里包含经过验证的 6 种营销方式清单。"},
    {"id":"case-proya-betaine-skincare-benchmark","title":"案例：贝泰妮招股书——敏感肌市场的完整画像","group":"E","insight":"一份招股书系统拆解后，等于免费拿到顶级咨询公司级别的行业分析报告。","failure":"重复做已被披露的行业分析。","frameworks":"tool-yitang-financial-report-intelligence、tool-yitang-comparable-company-selection","surprise":"敏感肌人群占比、复购率、线上渠道占比全在招股书。"},
    {"id":"case-yitang-beauty-device-overseas-sales","title":"案例：美容仪出海——用行业报告判断海外市场","group":"E","insight":"出海不需要每个市场都飞，先用行业报告筛选 2-3 个潜力国家，再实地验证。","failure":"无差别实地考察所有潜在市场。","frameworks":"framework-doris-industry-report-4step、tool-yitang-overseas-research","surprise":"不出国门即可先筛掉大部分市场。"},
    {"id":"case-yitang-sanjieke-benchmark-failure","title":"案例：对标三节课做C端，半年后发现对方已转型B端","group":"E","insight":"专家访谈得到的是“静态快照”，必须有时间戳意识：信息是何时产生的？现在是否仍然成立？","failure":"把专家访谈的静态快照当长期真理。","frameworks":"framework-yitang-expert-interview-10steps、dk-yitang-expert-interview-5-traps","surprise":"三轮饭局打听到的内部模型，半年后完全失效。"},
    {"id":"case-yitang-track-selection-research","title":"案例：一堂赛道选择——用调研方法论选创业方向","group":"F","insight":"用 OSL 五步法系统做赛道调研，既验证可行性也明确差异化定位。","failure":"凭感觉或追风口选赛道。","frameworks":"framework-yitang-oscar-research、yt-research-osl-framework","surprise":"一堂自己就是调研方法论的最佳案例。"},
    {"id":"case-xian-franchise-location-decision","title":"案例：西安加盟选址——系统调研vs拍脑袋","group":"F","insight":"异地加盟最大风险是用一线城市数据推断新一线城市，必须拿到目标城市真实数据。","failure":"“想当然”式调研只看样板店和官方材料。","frameworks":"tool-yitang-store-franchise-research、tool-yitang-field-research","surprise":"最该访谈的是已关店加盟商和商业地产中介。"},
    {"id":"case-yitang-senior-university-product-design","title":"案例：老年大学——用假设链逐层验证赛道可行性","group":"F","insight":"不要直接回答“我能做吗”，把问题拆成依赖链逐层验证，L1 不成立则 L2/L3 不用看。","failure":"跳过基础假设直接回答自身可行性。","frameworks":"tool-yitang-user-interview-5steps、dk-yitang-research-question-quality","surprise":"“我能切入什么细分”在“有没有商业模式”未验证前不重要。"},
    {"id":"case-liutao-electric-bike-localization","title":"案例：电动车出海本地化——从0调研目标市场","group":"F","insight":"出海的第一个决策不是“选哪个国家”，而是建立一套可重复的海外市场评估框架。","failure":"靠单份报告下结论。","frameworks":"framework-yitang-high-level-execution、tool-yitang-overseas-research","surprise":"调研应成为可持续的认知基础设施，而非一次性行为。"},
    {"id":"case-yitang-ai-time-management-coach","title":"案例：AI辅助调研——时间管理教练产品验证","group":"F","insight":"AI 可把调研从 2 周压缩到 2-3 天，但前提是人已掌握调研方法论。","failure":"让 AI 无方向地执行。","frameworks":"tool-yitang-ai-research-workflow、dk-yitang-ai-research-prompt-craft","surprise":"人机协作的瓶颈在人，不在 AI。"},
    {"id":"case-一堂-陈贤敏汉堡-hypothesis-validation","title":"案例：陈贤敏中式汉堡先开实验店验证关键假设","group":"F","insight":"资源越充足，越应克制愿望思维，把资源变成验证关键假设的工具而非扩张赌注。","failure":"跳过关键假设直接多店扩张。","frameworks":"concept-一堂-hypothesis-driven-business-methodology、yt-research-hypothesis-test、yt-entrepreneur-lean-validation","surprise":"有资本开 3 家店，却选择先开 1 家实验店。"},
    {"id":"case-一堂-无人餐厅-hypothesis-failure","title":"案例：一堂无人餐厅项目因忽视关键假设而失败","group":"F","insight":"未验证“机器人经营价值/行业机会/单元模型”等前置假设就 all in，最终现金流烧光。","failure":"把营销热度和美好愿望当成需求验证。","frameworks":"concept-一堂-hypothesis-driven-business-methodology、concept-一堂-key-assumptions、yt-lean-assumption-verification-3means","surprise":"有京东背书和大量媒体流量仍失败，机器人维护人力反而比传统餐厅还多。"},
]
